    if parser == 'lalr':
        if lexer is None:
            raise ValueError('The LALR parser requires use of a lexer')
        if lexer == 'standard':
            return LALR_TraditionalLexer
        if lexer == 'contextual':
            return LALR_ContextualLexer
        if issubclass(lexer, Lexer):
            class LALR_CustomLexerWrapper(LALR_CustomLexer):
                def __init__(self, lexer_conf, parser_conf, options=None):
                    super().__init__(lexer, lexer_conf, parser_conf, options=options)
                def init_lexer(self):
                    self.lexer = lexer(self.lexer_conf)
            return LALR_CustomLexerWrapper
        raise ValueError('Unknown lexer: %s' % lexer)
    if parser == 'earley':
        if lexer == 'standard':
            return Earley
        if lexer == 'dynamic':
            return XEarley
        if lexer == 'dynamic_complete':
            return XEarley_CompleteLex
        if lexer == 'contextual':
            raise ValueError('The Earley parser does not support the contextual parser')
        raise ValueError('Unknown lexer: %s' % lexer)
    if parser == 'cyk':
        if lexer == 'standard':
            return CYK
        raise ValueError('CYK parser requires using standard parser.')
    raise ValueError('Unknown parser: %s' % parser)"}, {"qualname": "lark/exceptions.py::UnexpectedInput.match_examples", "source": "def match_examples(self, parse_fn, examples, token_type_match_fallback=False, use_accepts=False):
    assert self.state is not None, "Not supported for this exception"
    examples = examples.items() if isinstance(examples, dict) else examples
    candidate = (None, False)
    for i, (label, example) in enumerate(examples):
        assert not isinstance(example, STRING_TYPE)
        for j, malformed in enumerate(example):
            try:
                parse_fn(malformed)
            except UnexpectedInput as ut:
                if ut.state != self.state:
                    continue
                if use_accepts and ut.accepts != self.accepts:
                    logger.debug("Different accepts with same state[%d]: %s != %s at example [%s][%s]" %
                                (self.state, self.accepts, ut.accepts, i, j))
                    continue
                try:
                    if ut.token == self.token:
                        logger.debug("Exact Match at example [%s][%s]" % (i, j))
                        return label
                    if token_type_match_fallback and ut.token.type == self.token.type and not candidate[-1]:
                        logger.debug("Token Type Fallback at example [%s][%s]" % (i, j))
                        candidate = label, True
                except AttributeError:
                    pass
                if not candidate[0]:
                    logger.debug("Same State match at example [%s][%s]" % (i, j))
                    candidate = label, False
    return candidate[0]"}, {"qualname": "lark/load_grammar.py::Grammar.compile", "source": "def compile(self, start):
    term_defs = deepcopy(list(self.term_defs))
    rule_defs = [(n,p,nr_deepcopy_tree(t),o) for n,p,t,o in self.rule_defs]
    transformer = PrepareLiterals() * TerminalTreeToPattern()
    terminals = [TerminalDef(name, transformer.transform(term_tree), priority)
                 for name, (term_tree, priority) in term_defs if term_tree]
    anon_tokens_transf = PrepareAnonTerminals(terminals)
    transformer = PrepareLiterals() * PrepareSymbols() * anon_tokens_transf
    transformer *= ApplyTemplates(rule_defs)
    ebnf_to_bnf = EBNF_to_BNF()
    rules = []
    i = 0
    while i < len(rule_defs):
        name, params, rule_tree, options = rule_defs[i]
        i += 1
        if params:
            continue
        rule_options = RuleOptions(keep_all_tokens=True) if options and options.keep_all_tokens else None
        ebnf_to_bnf.rule_options = rule_options
        ebnf_to_bnf.prefix = name
        anon_tokens_transf.rule_options = rule_options
        tree = transformer.transform(rule_tree)
        res = ebnf_to_bnf.transform(tree)
        rules.append((name, res, options))
    rules += ebnf_to_bnf.new_rules
    assert len(rules) == len({name for name, _t, _o in rules}), "Whoops, name collision"
    rule_tree_to_text = RuleTreeToText()
    simplify_rule = SimplifyRule_Visitor()
    compiled_rules = []
    for name, tree, options in rules:
        simplify_rule.visit(tree)
        expansions = rule_tree_to_text.transform(tree)
        for i, (expansion, alias) in enumerate(expansions):
            if alias and name.startswith('_'):
                raise GrammarError("Rule %s is marked for expansion (it starts with an underscore) and isn't allowed to have aliases (alias=%s)" % (name, alias))
            empty_indices = [x==_EMPTY for x in expansion]
            if any(empty_indices):
                exp_options = copy(options) or RuleOptions()
                exp_options.empty_indices = empty_indices
                expansion = [x for x in expansion if x!=_EMPTY]
            else:
                exp_options = options
            assert all(isinstance(x, Symbol) for x in expansion), expansion
            rule = Rule(NonTerminal(name), expansion, i, alias, exp_options)
            compiled_rules.append(rule)
    if len(set(compiled_rules)) != len(compiled_rules):
        duplicates = classify(compiled_rules, lambda x: x)
        for dups in duplicates.values():
            if len(dups) > 1:
                if dups[0].expansion:
                    raise GrammarError("Rules defined twice: %s\n\n(Might happen due to colliding expansion of optionals: [] or ?)"
                                       % ''.join('\n  * %s' % i for i in dups))
                assert len({(r.alias, r.order, r.options) for r in dups}) == len(dups)
        compiled_rules = list(set(compiled_rules))
    while True:
        c = len(compiled_rules)
        used_rules = {s for r in compiled_rules
                            for s in r.expansion
                            if isinstance(s, NonTerminal)
                            and s != r.origin}
        used_rules |= {NonTerminal(s) for s in start}
        compiled_rules, unused = classify_bool(compiled_rules, lambda r: r.origin in used_rules)
        for r in unused:
            logger.debug("Unused rule: %s", r)
        if len(compiled_rules) == c:
            break
    used_terms = {t.name for r in compiled_rules
                         for t in r.expansion
                         if isinstance(t, Terminal)}
    terminals, unused = classify_bool(terminals, lambda t: t.name in used_terms or t.name in self.ignore)
    if unused:
        logger.debug("Unused terminals: %s", [t.name for t in unused])
    return terminals, compiled_rules, self.ignore"}, {"qualname": "lark/parsers/earley_forest.py::ForestVisitor.visit", "source": "def visit(self, root):
    visiting = set()
    path = []
    input_stack = deque([root])
    vpno = getattr(self, 'visit_packed_node_out')
    vpni = getattr(self, 'visit_packed_node_in')
    vsno = getattr(self, 'visit_symbol_node_out')
    vsni = getattr(self, 'visit_symbol_node_in')
    vino = getattr(self, 'visit_intermediate_node_out', vsno)
    vini = getattr(self, 'visit_intermediate_node_in', vsni)
    vtn = getattr(self, 'visit_token_node')
    oc = getattr(self, 'on_cycle')
    while input_stack:
        current = next(reversed(input_stack))
        try:
            next_node = next(current)
        except StopIteration:
            input_stack.pop()
            continue
        except TypeError:
            pass
        else:
            if next_node is None:
                continue
            if id(next_node) in visiting:
                oc(next_node, path)
                continue
            input_stack.append(next_node)
            continue
        if not isinstance(current, ForestNode):
            vtn(current)
            input_stack.pop()
            continue
        current_id = id(current)
        if current_id in visiting:
            if isinstance(current, PackedNode):
                vpno(current)
            elif current.is_intermediate:
                vino(current)
            else:
                vsno(current)
            input_stack.pop()
            path.pop()
            visiting.remove(current_id)
            continue
        visiting.add(current_id)
        path.append(current)
        if isinstance(current, PackedNode):
            next_node = vpni(current)
        elif current.is_intermediate:
            next_node = vini(current)
        else:
            next_node = vsni(current)
        if next_node is None:
            continue
        if not isinstance(next_node, ForestNode) and not isinstance(next_node, Token):
            next_node = iter(next_node)
        elif id(next_node) in visiting:
